mapper.select:
SELECT DISTINCT s.*
FROM students s
LEFT JOIN students_courses sc ON s.id = sc.student_id
LEFT JOIN application_statuses aps ON sc.id = aps.students_courses_id


    AND s.full_name LIKE CONCAT('%', #{fullName}, '%')


    AND s.furigana LIKE CONCAT('%', #{furigana}, '%')


    AND s.nickname LIKE CONCAT('%', #{nickname}, '%')


    AND s.age >= #{minAge}


    AND s.age <= #{maxAge}


    AND s.gender = #{gender}


    AND s.city LIKE CONCAT('%', #{city}, '%')


    AND sc.course LIKE CONCAT('%', #{course}, '%')


    AND aps.status = #{status}
